    26→import {SyncOptions} from "./options.js";
    27→import {getAllDescendantBlocks, getDescendantBlocks, getUnknownAndAncestorBlocks} from "./utils/pendingBlocksTree.js";
    28→
    29→const MAX_ATTEMPTS_PER_BLOCK = 5;
    30→const MAX_KNOWN_BAD_BLOCKS = 500;
    31→const MAX_PENDING_BLOCKS = 100;
    32→
    33→export class UnknownBlockSync {
    34→  /**
    35→   * block RootHex -> PendingBlock. To avoid finding same root at the same time
    36→   */
    37→  private readonly pendingBlocks = new Map<RootHex, PendingBlock>();
    38→  private readonly knownBadBlocks = new Set<RootHex>();
    39→  private readonly proposerBoostSecWindow: number;
    40→  private readonly maxPendingBlocks;
    41→  private subscribedToNetworkEvents = false;
    42→
    43→  private engineGetBlobsCache = new Map<RootHex, BlobAndProof | null>();
    44→  private blockInputsRetryTrackerCache = new Set<RootHex>();
    45→  private peerBalancer: UnknownBlockPeerBalancer;
    46→
    47→  constructor(
    48→    private readonly config: ChainForkConfig,
    49→    private readonly network: INetwork,
    50→    private readonly chain: IBeaconChain,
    51→    private readonly logger: Logger,
    52→    private readonly metrics: Metrics | null,
    53→    private readonly opts?: SyncOptions
    54→  ) {
    55→    this.maxPendingBlocks = opts?.maxPendingBlocks ?? MAX_PENDING_BLOCKS;
    56→    this.proposerBoostSecWindow = this.config.SECONDS_PER_SLOT / INTERVALS_PER_SLOT;
    57→    this.peerBalancer = new UnknownBlockPeerBalancer(this.network.custodyConfig);
    58→
    59→    if (metrics) {
    60→      metrics.syncUnknownBlock.pendingBlocks.addCollect(() => {
    61→        metrics.syncUnknownBlock.pendingBlocks.set(this.pendingBlocks.size);
    62→        metrics.syncUnknownBlock.knownBadBlocks.set(this.knownBadBlocks.size);
    63→        metrics.syncUnknownBlock.peerBalancer.peersMetaCount.set(this.peerBalancer.peersMeta.size);
    64→        metrics.syncUnknownBlock.peerBalancer.peersActiveRequestCount.set(this.peerBalancer.activeRequests.size);
    65→        metrics.syncUnknownBlock.peerBalancer.totalActiveRequests.set(this.peerBalancer.getTotalActiveRequests());
    66→      });
    67→    }
    68→  }
    69→
    70→  subscribeToNetwork(): void {
    71→    if (!this.opts?.disableUnknownBlockSync) {
    72→      // cannot chain to the above if or the log will be incorrect
    73→      if (!this.subscribedToNetworkEvents) {
    74→        this.logger.verbose("UnknownBlockSync enabled.");
    75→        this.network.events.on(NetworkEvent.unknownBlock, this.onUnknownBlock);
    76→        this.network.events.on(NetworkEvent.unknownBlockInput, this.onUnknownBlockInput);
    77→        this.network.events.on(NetworkEvent.unknownBlockParent, this.onUnknownParent);
    78→        this.network.events.on(NetworkEvent.peerConnected, this.onPeerConnected);
    79→        this.network.events.on(NetworkEvent.peerDisconnected, this.onPeerDisconnected);
    80→        this.subscribedToNetworkEvents = true;
    81→      }
    82→    } else {
    83→      this.logger.verbose("UnknownBlockSync disabled by disableUnknownBlockSync option.");
    84→    }
    85→  }
    86→
    87→  unsubscribeFromNetwork(): void {
    88→    this.logger.verbose("UnknownBlockSync disabled.");
    89→    this.network.events.off(NetworkEvent.unknownBlock, this.onUnknownBlock);
    90→    this.network.events.off(NetworkEvent.unknownBlockInput, this.onUnknownBlockInput);
    91→    this.network.events.off(NetworkEvent.unknownBlockParent, this.onUnknownParent);
    92→    this.network.events.off(NetworkEvent.peerConnected, this.onPeerConnected);
    93→    this.network.events.off(NetworkEvent.peerDisconnected, this.onPeerDisconnected);
    94→    this.subscribedToNetworkEvents = false;
    95→  }
    96→
    97→  close(): void {
    98→    this.unsubscribeFromNetwork();
    99→    // add more in the future if needed
